24	/// Run lint rules over an [`Expr`] syntax node.
25	pub(crate) fn expression(expr: &Expr, checker: &Checker) {
26	    match expr {
27	        Expr::Subscript(subscript @ ast::ExprSubscript { value, slice, .. }) => {
28	            // Ex) Optional[...], Union[...]
29	            if checker.any_rule_enabled(&[
30	                Rule::FutureRewritableTypeAnnotation,
31	                Rule::NonPEP604AnnotationUnion,
32	                Rule::NonPEP604AnnotationOptional,
33	            ]) {
34	                if let Some(operator) = typing::to_pep604_operator(value, slice, &checker.semantic)
35	                {
36	                    if checker.is_rule_enabled(Rule::FutureRewritableTypeAnnotation) {
37	                        if !checker.semantic.future_annotations_or_stub()
38	                            && checker.target_version() < PythonVersion::PY310
39	                            && checker.target_version() >= PythonVersion::PY37
40	                            && checker.semantic.in_annotation()
41	                            && !checker.settings().pyupgrade.keep_runtime_typing
42	                        {
43	                            flake8_future_annotations::rules::future_rewritable_type_annotation(
44	                                checker, value,
45	                            );
46	                        }
47	                    }
48	                    if checker.any_rule_enabled(&[
49	                        Rule::NonPEP604AnnotationUnion,
50	                        Rule::NonPEP604AnnotationOptional,
51	                    ]) {
52	                        if checker.source_type.is_stub()
53	                            || checker.target_version() >= PythonVersion::PY310
54	                            || (checker.target_version() >= PythonVersion::PY37
55	                                && checker.semantic.future_annotations_or_stub()
56	                                && (checker.semantic.in_annotation()
57	                                    || checker.semantic.in_string_type_definition())
58	                                && !checker.settings().pyupgrade.keep_runtime_typing)
